# Try: replace each 2 with the count of 3-neighbor cells
test = [
    [3, 3, 3, 3, 2, 2, 3],
    [2, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 2],
    [3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3]
]

output_neighbor_count = [row[:] for row in test]

def count_3_neighbors(r, c, grid):
    count = 0
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < 5 and 0 <= nc < 7:
            if grid[nr][nc] == 3:
                count += 1
    return min(count, 10)  # cap at 9

for r in range(5):
    for c in range(7):
        if test[r][c] == 2:
            output_neighbor_count[r][c] = count_3_neighbors(r, c, test)

print('Neighbor count:', json.dumps(output_neighbor_count))

